-- 3351 (release 48, part MAP; docs/changes/2026-11-20-r48-map-people.md): the guides and the academy for people on the live map (3350).
-- Academy: one section, People on the live map (fleet, customer service, Sales, field, admin), one lesson and its quiz;
-- staff who had passed everything get 7 days for it.
-- Guides: the chapters changed in docs/guides/content (generated by supabase/seed/3351_gen_guides.mjs): admin/people-and-access,
-- va/start-here, va/live-visitors-and-live-chat, field/my-jobs, renter/before-pickup, owner/notices-profile-and-leaving. SCHEMA_MARKER 3351.
create temp table r48map_done on commit drop as select distinct e.user_id from academy_enrollments e where app.academy_done(e.user_id);
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-map-people', 'People on the live map', 'When staff, renters and owners show on the live map, who sees them, and the electronic monitoring policy.', array['va/start-here', 'field/my-jobs', 'admin/people-and-access']::text[])
  on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-map-people'), 1, 'On duty only', '[{"caption":"The policy","say":"The first time, you accept the electronic monitoring policy. You get a copy by email. Ontario law asks for it.","visual":{"kind":"title","heading":"On duty only","text":"The electronic monitoring policy"}},{"caption":"When it shares","say":"While you are clocked in or on a job, the CarmaCars app or the staff portal shares where you are with Admins and Fleet. Off duty, nothing is taken.","visual":{"kind":"list","heading":"Shared","items":["On shift","On a job","Never off duty"]}},{"caption":"Renters and owners","say":"Renters and owners show only with their phone''s permission, and only two hours either side of a pickup or return. Anyone can turn it off, except staff during an active job.","visual":{"kind":"list","heading":"App users","items":["With permission","Pickup and return only","Can turn it off"]}}]'::jsonb)
  on conflict do nothing;
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values
  ((select id from academy_sections where slug = 'r48-map-people'), 1, 'You clocked out an hour ago. Is your location on the live map?', '["Yes, the last place I was","No: off duty nothing is taken or shown","Only to Admins"]'::jsonb, 1, 'Only while you are on shift or on a job. When you clock out, your position is deleted.'),
  ((select id from academy_sections where slug = 'r48-map-people'), 2, 'A field job is in progress. Can you turn location sharing off?', '["Yes, any time","No: during an active job it stays on, and stops when the job is done","Only in the app"]'::jsonb, 1, 'During an active job sharing stays on; between jobs you can turn it off in Profile.'),
  ((select id from academy_sections where slug = 'r48-map-people'), 3, 'When does a renter show on the map?', '["Whenever the app is open","Only with permission, two hours either side of a pickup or return","For the whole rental"]'::jsonb, 1, 'Precise only around a pickup or return, and only with the phone''s or browser''s permission.')
  on conflict do nothing;
insert into academy_path_sections (path_code, section_id, sort)
select pc, (select id from academy_sections where slug = 'r48-map-people'), coalesce((select max(sort) from academy_path_sections where path_code = pc), 0) + 1
  from unnest(array['fleet', 'cs', 'sales_remote', 'sales_in_person', 'field', 'admin']) pc
 where not exists (select 1 from academy_path_sections x where x.path_code = pc and x.section_id = (select id from academy_sections where slug = 'r48-map-people'));
update academy_enrollments e set lock_from = greatest(e.lock_from, now() + interval '7 days') from r48map_done d where e.user_id = d.user_id and e.gate;

-- GUIDES 3351 START (generated by supabase/seed/3351_gen_guides.mjs from docs/guides/content; do not edit by hand)
select app.guide_release_section('renter', 'before-pickup', 'chapter', 'sign-and-pay', 'Your booking is confirmed. A few things are left: your licence photos, a selfie and proof of coverage, a signature from each additional driver, and the deposit.

## What we still need from you

While a request or booking is not complete, everything it still needs is in one list, **To do**, under the steps on **Trips** and on the booking: one line for each thing, with its state and a small button. The red button of **Do this next** is always the first thing to do.

| State | What it means |
| --- | --- |
| Needed | Send it: press the button on the line |
| Not accepted | We could not accept what you sent: the reason is on the line, send it again |
| Under review | We have it and a person on our team is checking it |
| Done | Nothing more to do |

The lines are what this booking needs: your licence (front and back) and a selfie for each driver, proof of coverage (not with the Protection Plan), signing and paying, the deposit, each additional driver accepting the terms, your date of birth and your home address. On the booking, the details the agreement needs are filled in right there, under **Your details for the agreement**. Our reminders name the same things.

Each line says exactly what is missing. With your own insurance (OPCF 27) you send two pages: the **pink slip** (the insurance card for your own car) and the **OPCF 27 endorsement page** of your policy. If one is missing, the line says which one ("We have your OPCF 27 endorsement page. Still needed: your pink slip"), and its button opens that upload with the page chosen. Next to each upload is an example picture of the page with the parts that must show circled: your name, the policy number, the dates, the insurer and, on the endorsement page, the OPCF 27 line. Find it in your insurer''s app or website, in your email, or in your car''s glovebox. Put it flat, get all four corners in the photo, and avoid glare.

## Your booking page

Every booking opens with a large photo of your car, its name, the status and a clock: "Pickup in 2 days 4 h", or "Return by Sun 7 PM" while you have the car.

1. Open **Trips**, then your booking. The status is on the photo, for example Confirmed, with your booking number.
2. Under the photo: when and where you pick up and return the car (tap a place to open it in Maps), the kilometres included, the fuel rule and the deposit.
3. **Do this next**, at the top, tells you the one thing still needed, with its red button, for example **Upload documents**, and the time left before pickup. Under it, your steps: done, now (**Your turn**) and later. When nothing is needed it says when and where to pick up the car, with **Add to calendar**.
4. Manage your trip holds **Licence and coverage**, **Extend**, **Ask to change dates**, **Message us**, **Call us**, **Add a driver**, **Documents** and **Cancel booking**.

![](/guides/img/renter-08-booking-confirmed-desktop-b5603da5.jpg "desktop; size: 1440 972; address: carmacars.ca/account/bookings/CC-10003; pins: 1 10.4 54.9, 2 9.4 78.9, 3 92.4 76.9")

Money, on the right (below on a phone), shows what you paid and what is owing, part by part, with a **Pay** button when something is open and your receipts. **Price details** opens every line of the price. The steps under **Do this next** show how far along you are: approve the offer, sign and pay, licence and insurance, pick up, return, final statement. A step finished since your last visit ticks over as the bar moves.

## Your rental, step by step

**Your rental, step by step** on your booking opens the walkthrough: the whole rental in four stages, Before pickup, At pickup, On the road and The return.

1. Press **Start the walkthrough** (**Continue** once you have begun). The top shows how many steps are done and which stage you are at.
2. The step to do now is in black at the top. A task opens its page, for example **Add your licence** or **Sign the agreement**, and is ticked once it is done. A step to read (what to bring, where we meet, your own photos, the road rules, what to do if something goes wrong, how to bring the car back) has **Got it**.
3. At pickup, the walk-around: we photograph the car with you and you sign the condition report on your phone. Once done, **See the photo report** opens every photo.
4. Every stage is listed below with its steps, so you can read ahead.

## Upload your licence, selfie and coverage

Do this at least 24 hours before pickup. It takes a few minutes with your phone.

1. On your booking, press **Upload documents** (or **Licence and coverage**).
2. Licence, front: lay the licence on a dark surface with all four corners visible. Press **Take a photo**, or **Choose from my photos** for a photo already on your phone.
3. Licence, back: do the same for the back.
4. Selfie with your licence: hold the licence beside your face, then press **Take selfie**.
5. Coverage for damage to the car: add what your option asks for, then press **Take a photo** or **Choose from my photos** (a PDF works too). Not sure your credit card covers rentals? Use the card coverage checker first.

While your booking still needs them, **Your trips** shows **Upload your licence**, **Upload proof of insurance** and **Check if your credit card covers rentals**, and our request and offer emails link straight to the licence upload.

![](/guides/img/renter-09-verify-desktop-d20f668d.jpg "desktop; size: 1440 1232; address: carmacars.ca/account/bookings/CC-10003/verify; pins: 2 18.5 65.3, 3 50.0 63.6, 4 81.2 63.6, 5 50.0 95.3")

| Your option | What we need |
| --- | --- |
| Option 1, OPCF 27 on your own policy | Your insurer, the policy number and its expiry (after your return date), then two pages: your **pink slip** (the liability insurance card) and the **OPCF 27 endorsement page**, each a PDF or a photo. Send both before you pay: the payment opens once they are in. |
| Option 2, your credit card''s rental coverage | Pay with that card: it must be a credit card (debit and prepaid cards are refused) in your name. Search for your card (the bank and the card''s name) and pick it: the page tells you at once whether it covers this car (the card''s value limit, the kinds of car it leaves out, the most days). Then tick and confirm. Not on the list? Tick **My card is not on the list** and type its name: our team checks it. The card''s benefits document is optional. |
| Option 3, the CarmaCars Protection Plan | Ask for it on your booking; we confirm it once it is active. |

> Good to know: Which cards include rental car coverage? `carmacars.ca/credit-card-rental-coverage` lists them, with each card''s car value limit (MSRP), its longest rental and a link to its guide. Most cards stop at a car priced $65,000 or $85,000, and some of our cars are priced higher. Only your card''s issuer decides a claim: call the number on the back of your card before you rent.

> Tip: A person checks your proof and approves it, or tells you what to fix. The car is handed over only once it is approved. Changing your option replaces the earlier proof. We remind you 48 and 24 hours before pickup while it is missing. We delete licence and face photos 90 days after your rental ends.

## Additional drivers

Each additional driver signs the agreement with their own link.

1. When the agreement is ready, each driver with an email gets their own signing link.
2. On your booking, press **Copy their signing link** to send it yourself, or **Send a new link**.
3. Each driver adds their own licence photos and selfie, like you did.

> Watch out: Signing links expire after 72 hours. A new link ends the older one, so always send the newest.

## Add something to your trip

Until 24 hours before pickup (or the notice an add-on needs), add add-ons from your booking.

1. On your booking, under Add-ons, press **Add something to your trip**.
2. Tick the add-on you want. Its price shows below.
3. Press **Add and pay**. It is charged at once on the card you paid with, and shows on your booking and receipt.
4. A chauffeur needs our confirmation: press **Ask for it**. We confirm it and charge your card then.

No card on file for this booking? The add-on is added and waits for payment: press **Pay for your add-ons** under Add-ons, enter a card and press **Pay**. It is charged at once; that card is not kept.

> Tip: If you cancel, add-ons are refunded like the rest of your booking. Flowers and a chauffeur are not refunded once their notice before pickup has started.

## What to bring to pickup

- Your original licence. A photo is not enough.
- The card you paid with. The deposit is taken on it about an hour before pickup.
- A few minutes to walk around the car with us. We photograph it together.

## Check in yourself (release 28)

From 24 hours before pickup, **Check in yourself** on your booking: take the photos of the car as you get it (pick them all at once from your camera roll: all sides, odometer, fuel gauge, inside, any damage), the odometer and the fuel. If your booking is ready, you are checked in at once; otherwise a team member confirms it. If you do not take the photos, we take them.

## If we change your coverage (release 35)

If your card does not cover the car, or you ask for the CarmaCars Protection Plan, our team can switch your booking for you. You get an email with what changed and the new total. On an offer you approve the new price. On a booking you have paid, any extra is sent to you as a secure payment link, or you pay it from your booking page. You then do not need to send a card coverage document. If you go back to your card, the booking page asks you to confirm it again.

## Your accident card

Your booking shows your **Accident card**: what to do after an accident, and the coverage of this booking.

- With your own auto policy (OPCF 27): your insurer and policy number, as on the proof you uploaded.
- With your credit card coverage: the card and its coverage provider.
- With the Protection Plan: the provider, the policy number, the claims phone and your plan reference.

Press **Print it** to print the card at its size for the glovebox, or keep the page on your phone.

### Your name and date of birth
Set them in your profile. Once your licence is verified they must match it: a change is sent as a correction request, shown as waiting until our team checks it against your licence.

## If your card does not cover the car

The page says why: the card has no rental car damage coverage, the car is worth more than the card''s limit, the card leaves out this kind of car, or the rental is longer than the card allows. Choose **Use OPCF 27 on my policy instead** or **Ask for the Protection Plan** just below.

## Change my protection

How damage to the car is covered can be changed on your booking page, under **Protection**, once you approve the offer and until you return the car.

1. Press **Change my protection**. You see the three options with their prices: your own insurance (OPCF 27), your credit card''s coverage, or the CarmaCars Protection Plan.
2. Credit card coverage: choose your card from our list. It counts only if that card covers this car, and you tick that you will pay with it. Otherwise, OPCF 27: tick that you will upload your policy (the pink slip and the endorsement page). Otherwise, the Protection Plan.
3. The Protection Plan applies at once: pay the difference with **Pay** on your booking. Moving off the Protection Plan needs your proof (a photo or PDF); our team checks it and the change applies once approved. You can withdraw the request while it waits.

During your trip you can add the Protection Plan; your own insurance or card coverage is set before pickup. After damage is reported, the protection stays as it was.
